window.STORY_CHAPTERS["cff895e03c1ff5df8"]={"id":"cff895e03c1ff5df8","lines":[{"uid":"talk.vc.home_touch_dil_3#originalText","id":"talk.vc.home_touch_dil_3","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"那里有着黑暗领域……不，是世界上最优秀的头脑。","en":"The greatest mind in the Dark Territory... No.. in the world, is right there.","ja":"そこには、ダークテリトリーで……いえ、世界で最も優秀な頭脳が入っておりますわ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dil_4#originalText","id":"talk.vc.home_touch_dil_4","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"只要是皇帝陛下所希望，现在马上也……","en":"If it his majesty's wish, I will get to it right away..","ja":"皇帝陛下のお望みなら今すぐにでも……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dil_5#originalText","id":"talk.vc.home_touch_dil_5","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"就算我在睡觉，那些鼠辈的攻击也无法伤害到我。","en":"Even if I was asleep, it would be difficult for a bunch of scoundrels to lay a finger on me.","ja":"たとえ私が寝ていたとしても不埒な輩の攻撃が、私を傷つけることはかないません"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_dil_8#originalText","id":"talk.vc.home_touch_dil_8","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"这是多么强大的实力……凭这般实力，集成骑士也能轻松收拾掉吧。","en":"Such amazing technique... With that, you can conquer even the Integrity Knights in a blink of the eye!","ja":"なんとたくましい腕でしょう……この腕ならば、整合騎士などひと息でひねってしまいますね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_1#originalText","id":"talk.vc.home_touch_edith_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嘿嘿……你摸着我，感觉好奇怪。","en":"Hehehe...being petted by you feels rather strange.","ja":"えへへ……あなたに撫でてもらうのってなんか変な感じ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_2#originalText","id":"talk.vc.home_touch_edith_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"等一下互相整理头发吧。我会给你弄个可爱的发型。","en":"Let's braid each other's hair later. I'll make your hair nice and cute.","ja":"後で、お互いの髪の毛整えようか可愛い髪型にしてあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_3#originalText","id":"talk.vc.home_touch_edith_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"呵呵，接下来换我了。我要尽情摸你！","en":"Hehe. My turn now! Lots of pats for you!","ja":"ふふ、次はあたしの番たっぷり撫でてあげる! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_4#originalText","id":"talk.vc.home_touch_edith_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"怎么啦？难道你很寂寞吗……好了，你过来一点。","en":"What's wrong? Feeling lonely? Then come closer.","ja":"どうしたの? もしかして寂しいのかな……ほら、もっとこっちに来て"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_5#originalText","id":"talk.vc.home_touch_edith_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"有点痒耶。很好，看我怎么回敬你！","en":"Hey! That tickles! Aha! The tables have turned!","ja":"ちょっとくすぐったいよほら、お返しだー! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_6#originalText","id":"talk.vc.home_touch_edith_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你这么大胆啊……我有点吓到了。","en":"Wow. Somebody sure is bold. Catch a girl off guard, why don't you!","ja":"なかなか大胆なのね……ちょっとびっくりしちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_7#originalText","id":"talk.vc.home_touch_edith_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"哼哼，你敢对我出手，就代表有做好受到反击的觉悟对吧！","en":"Hehe, since you did that to me, I'll assume you're prepared to have it done back to you!","ja":"ふふ、あたしにやったということはやられる覚悟もある、ってことね! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_edith_8#originalText","id":"talk.vc.home_touch_edith_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"怎么啦？我今天没进程，你可以尽情撒娇喔！","en":"What's wrong? I have no plans today, so I can pamper you all day if you need it.","ja":"どうしたの? 今日は予定がないからいっぱい甘えていいよ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_egome_1#originalText","id":"talk.vc.home_touch_egome_1","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"不、不要碰我的浏海！","en":"Hey! Hands off my hair!","ja":"ま、前髪に触るな!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_egome_2#originalText","id":"talk.vc.home_touch_egome_2","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"干嘛，你想打架吗！？","en":"What?! You wanna fight?!","ja":"なんだ、やるってのか!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_egome_3#originalText","id":"talk.vc.home_touch_egome_3","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"怎么了？有马蝇飞过来了吗？","en":"What, is there a horsefly around me?","ja":"どうした、アブでも飛んでたか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_egome_4#originalText","id":"talk.vc.home_touch_egome_4","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"往胸口的突刺……那是你流派的招式吗？","en":"Strikes towards the chest... Is that part of your style?","ja":"胸への突き……それはお前の流派の技なのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_egome_5#originalText","id":"talk.vc.home_touch_egome_5","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"唔……你居然那么轻易地戳我胸部……","en":"Grrr! How dare you... prod my chest so easily.","ja":"くっ……こうもたやすく俺の胸を突くとは……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_egome_8#originalText","id":"talk.vc.home_touch_egome_8","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"找本大爷有何贵干？","en":"What is it you want from me? I'm a busy man.","ja":"俺様に何の用だ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eiji_1#originalText","id":"talk.vc.home_touch_eiji_1","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"怎么了？我的头发有什么异状吗？","en":"What happened? Is there something weird with my hair?","ja":"どうしたんだ?僕の髪に、何かおかしなところがあるのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eiji_2#originalText","id":"talk.vc.home_touch_eiji_2","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"如果不戴着Augma，就会有种奇怪的感觉。毕竟我在「那边」一直都戴着。","en":"If you aren't wearing the Augma then it'll feel weird, since you’ve been wearing it this whole time.","ja":"オーグマーを付けてないとなんだかおかしな感じがするよあちらでは、ずっと付けているから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eiji_3#originalText","id":"talk.vc.home_touch_eiji_3","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"……啊，抱歉。我忽然想起以前，也有个像这样对我伸出手来的人．","en":"...No, sorry. It just reminds me of someone from long ago.","ja":"……いや、すまない昔、こうして手を差し伸べてくれた人を思い出してね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eiji_4#originalText","id":"talk.vc.home_touch_eiji_4","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"碰到身体的感觉也真的和现实世界一样呢。","en":"The senses on my body in this world really doesn't feel any different from the real world.","ja":"体が触れた感触も、本当に現実世界と変わらないんだな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eiji_5#originalText","id":"talk.vc.home_touch_eiji_5","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"我已经习惯胸口的疼痛了。这个疼痛是我的一部分，一直都没变。","en":"I've already gotten used to the pain in my chest. The pain is a part of me, and that will never change.","ja":"胸の痛みには、もう慣れたよこの痛みは僕の一部でそれはずっと変わらない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eiji_8#originalText","id":"talk.vc.home_touch_eiji_8","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"别这么轻易的就进行肢体接触比较好……总是无法保证有人不会因此而误会。","en":"It would be best not to casually touch someone... There are those who might get the wrong idea.","ja":"そう気軽にボディタッチをしない方がいい……勘違いする輩もいないとは限らないからな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eldrie_1#originalText","id":"talk.vc.home_touch_eldrie_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"随身粮食实在不合我的胃口，要忍受这味道还不如别吃。","en":"Army rations just taste terrible. I would rather go hungry.","ja":"どうも、携行食は口にあいませんなこれならば食べないほうがマシだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eldrie_2#originalText","id":"talk.vc.home_touch_eldrie_2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"这里有蔷薇的芬香……似乎充满了高贵的力量呢。","en":"This place smells of roses. It seems to be filled with a powerful, divine energy.","ja":"ここは薔薇の香りがする……高貴なる力に満ちているようです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eldrie_3#originalText","id":"talk.vc.home_touch_eldrie_3","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"您的头发也闪耀着美丽的光辉喔。","en":"Your hair is also very pretty.","ja":"あなたの御髪も、きれいに輝いておりますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eldrie_4#originalText","id":"talk.vc.home_touch_eldrie_4","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"如遇万一，我必定会守护您的。","en":"Whenever trouble is afoot, I shall leap to your aid.","ja":"有事の時には、必ず私がお守りいたします"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eldrie_5#originalText","id":"talk.vc.home_touch_eldrie_5","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"被您这样触碰，会稍稍有种难以言喻的感觉呢。","en":"Being touched like that makes me feel rather odd.","ja":"そのように触れられますと少々、妙な気持ちになりますな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eldrie_8#originalText","id":"talk.vc.home_touch_eldrie_8","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"您是否在呼唤本人艾尔多利耶‧辛赛西斯‧萨蒂汪呢？","en":"Do you have need of Eldrie Synthesis Thirty-One?","ja":"このエルドリエ・シンセシス・サーティワンをお呼びでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_entokia_integrator_1#originalText","id":"talk.vc.home_touch_entokia_integrator_1","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"你说身高吗？我当然要比涅吉欧高啰。","en":"How tall am I? Well, naturally, I'm taller than Negio.","ja":"身長ですか?そりゃオレのほうがネギオよりは高いっすよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_entokia_integrator_2#originalText","id":"talk.vc.home_touch_entokia_integrator_2","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"老师你怎么突然这么做？被人这样对待……我也是会还手的喔。","en":"What was that for? I'm tempted to do the same to you.","ja":"なんですか、いきなり?そんなんされたら……こっちもやり返しますよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_entokia_integrator_3#originalText","id":"talk.vc.home_touch_entokia_integrator_3","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"我对自己的体格还算有点自信，但实在比不上迪索尔巴德阁下呢。","en":"While I am confident in my own physical prowess, I don't hold a candle to Deusolbert.","ja":"体格にはある程度自信がありますが、デュソルバート殿にはさすがに負けますなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_entokia_integrator_4#originalText","id":"talk.vc.home_touch_entokia_integrator_4","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"老师，男人的胸部摸起来有什么意思？真搞不懂你。","en":"Master, why do you find touching another man's chest so amusing? You really are an enigma.","ja":"先生、男の胸触って何が楽しいんです?よくわからんお人だ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_entokia_integrator_5#originalText","id":"talk.vc.home_touch_entokia_integrator_5","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"对决是吗？这个嘛，你若下令我自然照办……但能不能下次再说？","en":"You wish to duel? Well, if you insist, I'll comply, but can't we do it later?","ja":"立ち合いっすか?そりゃ、やれと言われりゃやりますけど……今度にしません?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugene_1#originalText","id":"talk.vc.home_touch_eugene_1","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"嗯，瞄准眼睛和鼻子，会是有效的攻击呢。","en":"Hm. Aiming for the eyes or nose is certainly an effective attack.","ja":"ふむ、目や鼻を狙うのは効果的な攻撃だな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugene_2#originalText","id":"talk.vc.home_touch_eugene_2","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"嘿，我不会轻易被你掌握上方的。","en":"Whoa, there, I'm not gonna let you win that easily.","ja":"おっと、やすやすと上を取らせはせんぞ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugene_3#originalText","id":"talk.vc.home_touch_eugene_3","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"要狙击的话就瞄准肚子吧，瞄准头的动作太大了。","en":"If you're attacking, aim for the belly. The head moves too dramatically to get in a clean hit.","ja":"狙撃ならば腹を狙え頭は動きが大きすぎる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugene_4#originalText","id":"talk.vc.home_touch_eugene_4","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"喔唷？没想到你会主动挑战我。好，那就来战吧。","en":"Well, well, well. Looks who's taking the initiative. Okay, let's fight.","ja":"ほほう、お前から挑んでくるとは思わなかったぞ?さあ、闘おうか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugene_5#originalText","id":"talk.vc.home_touch_eugene_5","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"你想确认我的肉体吗？嗯，可以啊。","en":"What are you trying to do, check my body? Well, go ahead.","ja":"俺の肉体を確認しようというのか?まあ構わんぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugene_8#originalText","id":"talk.vc.home_touch_eugene_8","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"怎么了？有事吗？","en":"What? Do you want something?","ja":"どうした、なにか用か?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_1#originalText","id":"talk.vc.home_touch_eugeo_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯？我身上有什么吗？应该是在户外训练时沾上的吧……","en":"Hm, is there something there? Maybe that happened during outdoor training.","ja":"ん、なにかついてるかい? 外での教練の時かなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_2#originalText","id":"talk.vc.home_touch_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"被你这样对待后，总觉得自己就像变回小孩一样。","en":"Doing this makes me feel like a kid again.","ja":"なんか、そういうことされると自分が子どもになった気がするよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_3#originalText","id":"talk.vc.home_touch_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喂，瞄准眼睛犯规啦！","en":"Hey, don't go for the eyes! That's cheating.","ja":"おい、目を狙うのは反則だぞ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_4#originalText","id":"talk.vc.home_touch_eugeo_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我知道啦。你要我保持冷静，对吧？","en":"Understood. Stay calm, right?","ja":"わかってるよ落ち着いていけ、だろ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_5#originalText","id":"talk.vc.home_touch_eugeo_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"自从接受罗索学长的指导后，我发现自己好像练出许多肌肉。","en":"I feel a lot more muscular since Rosso started training me.","ja":"ゴルゴロッソ先輩に教わってからずいぶん筋肉がついた気がするよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_8#originalText","id":"talk.vc.home_touch_eugeo_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你找我吗？反正，又有事想拜托我了对吧。","en":"Did you call me? Let me guess, you need another favor.","ja":"呼んだ? どうせまた、何かの頼みごとだろうけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_child_1#originalText","id":"talk.vc.home_touch_eugeo_child_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是不是差不多该剪头发了呢……","en":"I probably need to cut my hair soon... It’s getting pretty long.","ja":"そろそろ、髪を切らないといけないかなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_child_2#originalText","id":"talk.vc.home_touch_eugeo_child_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"就算看了我的《史提西亚之窗》，也没什么有趣的吧？","en":"Why would you want to look at my \"Stacia Window\"? It would be pretty boring to you.","ja":"僕の《ステイシアの窓》なんか見ても、面白くないだろう? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_child_3#originalText","id":"talk.vc.home_touch_eugeo_child_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你要是摸了我的头，那个……我会觉得很痒的。","en":"Uh, could you not touch my head like that? It tickles!","ja":"頭を触られると、その……くすぐったいんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_child_4#originalText","id":"talk.vc.home_touch_eugeo_child_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，交换的时间到了。你就在那边休息吧。","en":"Oh, it's time to switch, isn't it? Well, you go have a rest then.","ja":"あ、交代の時間だねじゃあそっちで休んでてよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_child_5#originalText","id":"talk.vc.home_touch_eugeo_child_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你好大的胆子！那接下来就换我……搔你痒！","en":"Oh, now you've done it! Two can play at that game... Tickle, tickle!","ja":"やったな! それじゃ今度はこっちから……くすぐってやる! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_child_8#originalText","id":"talk.vc.home_touch_eugeo_child_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯？怎么了吗？你有话想对我说吗？","en":"Hm? What's wrong? Did you want to talk to me about something?","ja":"ん、どうしたの? 僕に話したいことでもある? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_integrator_6#originalText","id":"talk.vc.home_touch_eugeo_integrator_6","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_integrator_7#originalText","id":"talk.vc.home_touch_eugeo_integrator_7","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_integrator_8#originalText","id":"talk.vc.home_touch_eugeo_integrator_8","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fanatio_2#originalText","id":"talk.vc.home_touch_fanatio_2","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"像这样被您抚摸头部时，我该做何反应是好……","en":"I am not certain how I should respond to having my head patted in that manner.","ja":"そのように頭を撫でられるとどうしていいものか……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fanatio_4#originalText","id":"talk.vc.home_touch_fanatio_4","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"您就算触摸坚硬的铠甲，也无乐趣可言吧？","en":"The feel of cold armor can’t possibly be that interesting.","ja":"硬い鎧を触っても楽しくはありますまい?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fanatio_5#originalText","id":"talk.vc.home_touch_fanatio_5","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"如果要比突刺，我的《天穿剑》也不落于人后！","en":"If it's a competition of thrust attacks, my Heaven Piercing Sword will crush you!","ja":"突き技ならば、私の《天穿剣》も負けてはいません!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fanatio_6#originalText","id":"talk.vc.home_touch_fanatio_6","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"您的玩笑是否有些越界？","en":"Haven't you had too much fun?","ja":"少し戯れがすぎるのでは?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fanatio_7#originalText","id":"talk.vc.home_touch_fanatio_7","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"您这是……在逗弄我吗？还是……","en":"Is this...a game?","ja":"これは……戯れなのですかそれとも……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fanatio_8#originalText","id":"talk.vc.home_touch_fanatio_8","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"有什么事情吗？请尽管吩咐。","en":"Do you have any business with me?","ja":"なにかご用でしょうかなんなりと"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fizel_1#originalText","id":"talk.vc.home_touch_fizel_1","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"怎么了？我可没有长角喔。","en":"What? I don't have horns or anything.","ja":"なによ?あたしは、角なんか生えてません"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fizel_2#originalText","id":"talk.vc.home_touch_fizel_2","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"喂！我好歹也是一名集成骑士，不要把我当小孩子对待！","en":"Hey! I may not look it, but I'm an Integrity Knight. Stop treating me like a child!","ja":"ちょっと!これでも整合騎士なんだから子ども扱いはナシにして!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fizel_3#originalText","id":"talk.vc.home_touch_fizel_3","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"头发剪短比较好活动啊。虽然……我偶尔也会想跟涅尔一样留长发。","en":"Short hair is easier to manage. Though sometimes I wish I had long hair like Linel.","ja":"髪は短いほうが動きやすいのよ……たまに、ネルみたいな長いのもいいなって思うけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fizel_4#originalText","id":"talk.vc.home_touch_fizel_4","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"你想观察我吗？我是没差啦……","en":"Do you wish to observe me? I guess that’s fine...","ja":"あたしのこと観察したいの?別にいいけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fizel_5#originalText","id":"talk.vc.home_touch_fizel_5","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"喂，那里很敏感啦！讨厌，我要报复啰！","en":"Hey! That tickles! Fine, two can play at that game!","ja":"ちょ、そこは弱いの!もう、お返しするからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fizel_6#originalText","id":"talk.vc.home_touch_fizel_6","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"虽然我死了好几次，不过希望自己有确实成长。","en":"I have died many times before, but I hope I manage to grow up someday.","ja":"何回も死んじゃったけどちゃんと成長してくれたらいいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fizel_7#originalText","id":"talk.vc.home_touch_fizel_7","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"要刺的话，就要挑心脏的正中间。刺歪了可是很痛的。","en":"If you stab me, make sure it's in the center of my heart. I'm scared of the pain I'll feel if you're an inch off.","ja":"刺すなら、心臓の真ん中ねずれると、とっても痛いの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_fizel_8#originalText","id":"talk.vc.home_touch_fizel_8","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"怎么了？有什么好玩的事情吗？","en":"What's so funny?","ja":"どうしたの?何か面白いこと?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_frenica_1#originalText","id":"talk.vc.home_touch_frenica_1","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"我的头发很奇怪吗？","en":"Does my hair look strange?","ja":"私の髪、変かな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_frenica_2#originalText","id":"talk.vc.home_touch_frenica_2","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"……怎么啦？很痒喔。","en":"What? Haha. That tickles.","ja":"……なあに?くすぐったいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_frenica_3#originalText","id":"talk.vc.home_touch_frenica_3","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"我不讨厌被你摸，但还是会有点不好意思。","en":"I don't mind being massaged, but it's a bit embarrassing.","ja":"撫でられるのはイヤじゃないけどやっぱりちょっと恥ずかしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_frenica_4#originalText","id":"talk.vc.home_touch_frenica_4","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"呀！？讨、讨厌……你突然在做什么啦？","en":"Eek?! W-warn a girl first!","ja":"きゃっ!?も、もう……いきなりなあに?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_frenica_5#originalText","id":"talk.vc.home_touch_frenica_5","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"我对自己的胸部没什么自信……","en":"I'm not very confident about my chest.","ja":"私、胸にはあんまり自信ないから……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_frenica_8#originalText","id":"talk.vc.home_touch_frenica_8","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"怎么了？要一起出门吗？","en":"What's up? Want to go somewhere?","ja":"どうしたの?一緒にお出かけする?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_geero_1#originalText","id":"talk.vc.home_touch_geero_1","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"嗯……发生了什么事呢……","en":"Um... Do you need something?","ja":"えっと……何かありましたでしょうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_geero_2#originalText","id":"talk.vc.home_touch_geero_2","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"就算我脱下头盔……您还是会一如往常地对我吗？","en":"If I take my helmet off... Will you do the same?","ja":"兜を外しても……同じようにしてくださいますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_geero_3#originalText","id":"talk.vc.home_touch_geero_3","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"有时候我会把异常温热的手心放在头盔上降温","en":"Sometimes I place my palms on my helmet to cool them off.","ja":"たまに、火照った手のひらを兜に当てて冷やすことがありますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_geero_4#originalText","id":"talk.vc.home_touch_geero_4","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"我想盔甲应该没什么问题……","en":"I think my armor should be fine, but...","ja":"鎧の状態は問題ないかと思いますが……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_geero_5#originalText","id":"talk.vc.home_touch_geero_5","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"我的心中有著作为骑士的骄傲……","en":"I still have my pride as a knight...","ja":"騎士の誇りを胸に……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_geero_8#originalText","id":"talk.vc.home_touch_geero_8","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"有什么问题的话随时都可以跟我说","en":"Is there an order? Please ask if you need anything.","ja":"ご用命でしょうかなんなりとお申し付けください"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_golgorosso_1#originalText","id":"talk.vc.home_touch_golgorosso_1","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"你干嘛把手高举过头？是在思考什么新的秘藏奥义吗？","en":"Why are you holding your sword above your head? Did you come up with a new secret attack?","ja":"なんだ、上段に振りかぶって新しい秘奥義でも考えたのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_golgorosso_2#originalText","id":"talk.vc.home_touch_golgorosso_2","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"嘿，拜托你头部点到为止就好。","en":"Whoa, not the head, please.","ja":"おっと、頭は寸止めで頼むぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_golgorosso_3#originalText","id":"talk.vc.home_touch_golgorosso_3","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"还真是犀利的攻击。你的臂力变强了很多呢。","en":"Some pretty sharp swings you've got there. I can see your arms have gotten much stronger.","ja":"なかなか鋭い打ち込みだずいぶん腕の力が強くなってきたな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_golgorosso_4#originalText","id":"talk.vc.home_touch_golgorosso_4","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"朝身体正面而来的攻击，意外地难闪避呢。","en":"Head-on attacks are surprisingly difficult to dodge.","ja":"体の正面への攻撃は案外と避けづらいものだな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_golgorosso_5#originalText","id":"talk.vc.home_touch_golgorosso_5","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"好，这一击漂亮。就这样来比划一下吧！","en":"Good. Those were some nice attacks. Keep that up during our practice-duel!","ja":"よし、いい攻撃だぞこのまま手合わせと行こう!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_golgorosso_8#originalText","id":"talk.vc.home_touch_golgorosso_8","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"怎么了？有事吗？","en":"Do you need something from me?","ja":"どうした、なにか用事か?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_heathcliff_1#originalText","id":"talk.vc.home_touch_heathcliff_1","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"嘿唷，我可不会那么轻易就中招喔。","en":"Oh, there's no way that I can just simply strike a blow like that.","ja":"おっとそう簡単に、打撃を食らう訳にはいかないな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_heathcliff_2#originalText","id":"talk.vc.home_touch_heathcliff_2","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"有什么事吗？若是要参加公会，我随时欢迎。","en":"Any plans? If you wish to join the guild, you are welcome to anytime.","ja":"何か用事かね?ギルドへの参加なら、いつでも歓迎するぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_heathcliff_3#originalText","id":"talk.vc.home_touch_heathcliff_3","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"碰男人的脸有趣吗？你倒是有个挺怪的兴趣。","en":"Is it fun touching a man's face? Looks like you also have some odd hobbies.","ja":"男の顔を触って楽しいのか?君も変わった趣味を持っているな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_heathcliff_4#originalText","id":"talk.vc.home_touch_heathcliff_4","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"想要拿走这个盾可不是件容易的事喔。","en":"Drawing out this shield is not an easy thing to do.","ja":"この盾を抜くのは容易なことではないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_heathcliff_5#originalText","id":"talk.vc.home_touch_heathcliff_5","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"这是决斗的邀请吗？那么，我们换个地方吧。","en":"Is that a duel request? If that's the case, how about changing locations?","ja":"それは、デュエルの申し込みかな?だったら、場所を変えようじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_heathcliff_8#originalText","id":"talk.vc.home_touch_heathcliff_8","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"那不是认真的攻击吧？拿出杀了我的觉悟上吧！","en":"That wasn't a real attack, was it? If you're going to, then do so with the intent to kill.","ja":"それは本気の攻撃じゃないだろう?来るなら、殺す気で突いてこい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_hoveren_1#originalText","id":"talk.vc.home_touch_hoveren_1","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"您要慰劳我吗？我真是太感激太幸福了……！","en":"Are you trying to cheer me up? Thank you so much!","ja":"労ってくださるのですか?ありがたき幸せ……!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_hoveren_2#originalText","id":"talk.vc.home_touch_hoveren_2","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"这是保护头部用的重要防具","en":"It’s an item to protect your head.","ja":"頭部を守る大事な防具です"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_hoveren_3#originalText","id":"talk.vc.home_touch_hoveren_3","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"我的脸上有沾到了什么吗？","en":"Is there something on my cheek?","ja":"私の面頬に何かついていますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_hoveren_4#originalText","id":"talk.vc.home_touch_hoveren_4","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"不小心松懈了……刚刚碰到的若是剑的话，我的天命就会见底了吧","en":"I let my guard down... If that was a real sword, I probably would have lost my life.","ja":"油断いたしました……今のが剣でしたら、天命が底をついていたことでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_hoveren_5#originalText","id":"talk.vc.home_touch_hoveren_5","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"我们会尽责完成所有工作","en":"We’ve completed our duties.","ja":"我らが勤めを全ういたします"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_hoveren_8#originalText","id":"talk.vc.home_touch_hoveren_8","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"四旋剑何布雷恩·辛赛西斯·托尼希克斯，在此！随时听令！","en":"Hoveren Synthesis Twenty-Six of the Four Whirling Blades! Ready on your command!","ja":"四旋剣ホーブレン・シンセシス・トゥエニシックス、ここに!いつでもご命令ください!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_humbert_1#originalText","id":"talk.vc.home_touch_humbert_1","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"你这家伙，是在做什么！","en":"How dare you, you bastard!","ja":"何をするんだ、貴様!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_humbert_2#originalText","id":"talk.vc.home_touch_humbert_2","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"你少在那边念个没完！给我适可而止！","en":"Quit your yapping and shut up!","ja":"チョロチョロとうるさいヤツだ!いい加減にしろ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_humbert_3#originalText","id":"talk.vc.home_touch_humbert_3","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"呜……瞄准眼睛是何等卑鄙！","en":"Hmph! Only cheaters aim for the eyes!","ja":"くっ……目を狙うとは卑怯な!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_humbert_4#originalText","id":"talk.vc.home_touch_humbert_4","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"怎么，想跟我比试吗？如果你想求我指导剑术，先学会低头如何？","en":"What, you want a practice-duel? If you want my instruction, why don't you try bowing to me first?","ja":"なんだ、立ち合いでもしたいのか?剣の指導をしてほしいなら頭を下げたらどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_humbert_5#originalText","id":"talk.vc.home_touch_humbert_5","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"那种程度的攻击，我早就看穿了。","en":"I can see right through your jabs.","ja":"その程度の突き、見切ってるさ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_humbert_8#originalText","id":"talk.vc.home_touch_humbert_8","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"干嘛？没事就别靠近我。","en":"What? Stay away if you have no business with me.","ja":"なんだ?用事がないなら近づくな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_iskahn_1#originalText","id":"talk.vc.home_touch_iskahn_1","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"做什么！你该不会是在觉得我很矮吧！？","en":"What is it! Don't tell me you think I'm short, do ya?!","ja":"なんだよっ!まさか、俺の背が低いとか思ってんじゃねえだろうな!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_iskahn_2#originalText","id":"talk.vc.home_touch_iskahn_2","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"你觉得眼睛是弱点吗？哼，你戳我眼睛反而是你的手指会断掉喔？","en":"Did you think my weakness was my eye? I'll break your fingers off if you poke my eye. Got it?","ja":"目玉が弱点だと思ったか?ふん、俺の目をついたらお前の指が折れることになるぜ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_iskahn_3#originalText","id":"talk.vc.home_touch_iskahn_3","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"额头是身体最坚硬的部位。虽然比不上手臂和脚，但在战斗时也是很有用的武器。","en":"The forehead is the hardest section of the whole body. It's not like using your arms or legs, but it's more than enough of a weapon in battle.","ja":"額は体の中で最も固い部位だ腕や足ほどじゃねえが、戦闘では十分武器になる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_iskahn_4#originalText","id":"talk.vc.home_touch_iskahn_4","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"我们的肉体可不会输给剑或是箭。就算是龙的牙齿，也不能贯穿这皮肤。","en":"Our bodies won't lose to swords nor arrows! Even the fangs of a dragon won't be able to penetrate through this skin!","ja":"俺たちの肉体は、剣にも矢にも負けねえ。たとえ竜の牙だろうとこの皮膚を貫くことはできねえぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_iskahn_5#originalText","id":"talk.vc.home_touch_iskahn_5","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"我根本不需要铠甲。穿上那种东西会让动作变慢，只是个妨碍行动的东西。","en":"What's the point of even having armor around? It's just going to slow you down and get in the way.","ja":"鎧なんざ必要ねえんだよあんなの、動きが遅くなるだけのただの邪魔モンだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_iskahn_8#originalText","id":"talk.vc.home_touch_iskahn_8","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"很不错的进步。好，要就这样比试一下吗？","en":"That was a pretty good move. How about we do a match?","ja":"なかなかいい踏み込みだなよし、このまま一勝負するか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_jace_1#originalText","id":"talk.vc.home_touch_jace_1","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"头盔的保养也没有问题！","en":"I successfully got the helmet!","ja":"兜の手入れも万全です!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_jace_2#originalText","id":"talk.vc.home_touch_jace_2","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"唉……难道这是新训练的一环吗！？","en":"Right! ...Don’t tell me this is still part of the new training?!","ja":"はっ……もしやこれは新たな訓練の一貫でしょうか!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_jace_3#originalText","id":"talk.vc.home_touch_jace_3","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"为什么呢……当你这样对我的时候我就会感到安心","en":"Why is it I wonder... I feel so at ease.","ja":"何故でしょう……こうしていただくと心が安らぎます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_jace_4#originalText","id":"talk.vc.home_touch_jace_4","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"是！四旋剑杰伊斯‧辛赛西斯‧推尼史里在此！","en":"Jayce Synthesis Twenty-Three of the Four Whirling Blades, at your service!","ja":"はっ!四旋剣ジェイス・シンセシス・トゥエニスリー、ここに!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_jace_5#originalText","id":"talk.vc.home_touch_jace_5","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"你可以当我的比试对手吗请务必拜托了！","en":"Would you spar with me? Please!","ja":"立ち合いの相手をしてくださるのですか?ぜひお願いいたします!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_jace_8#originalText","id":"talk.vc.home_touch_jace_8","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"有什么困扰的事吗？有没有什么我帮得上忙的地方！？","en":"Is something the matter? Is there anything we can assist you with?!","ja":"なにか困りごとですか?我らにお力になれることはありませんか!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kagemune_1#originalText","id":"talk.vc.home_touch_kagemune_1","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"火精灵啊，果然耳朵也是尖尖的。","en":"Salamander ears are pointy, too, huh?","ja":"サラマンダーも、やっぱり耳が尖ってるんだよな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kagemune_2#originalText","id":"talk.vc.home_touch_kagemune_2","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"喂喂，你那只手想干嘛？不会是要摸我的头吧？","en":"Hey, now, why're you reaching out? I hope you're not going to pat my head.","ja":"おいおい、何だよその手はまさか俺の頭を撫でようってのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kagemune_3#originalText","id":"talk.vc.home_touch_kagemune_3","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"我们火精灵，整个种族都是红头发。","en":"All Salamanders have red hair.","ja":"サラマンダーってのは種族全員が赤髪なんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kagemune_4#originalText","id":"talk.vc.home_touch_kagemune_4","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"嗯？你叫我吗？","en":"Hm? You called me?","ja":"ん、呼んだか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kagemune_5#originalText","id":"talk.vc.home_touch_kagemune_5","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"就算心里明白是游戏，但还是会下意识护住胸部呢。","en":"Even though I know we're in VR, I still instinctively guard my chest.","ja":"ゲームだとわかっててもやっぱり胸はかばっちまうな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kagemune_8#originalText","id":"talk.vc.home_touch_kagemune_8","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"唷，你有要去哪吗？我这里随时有准备好喔。","en":"Going somewhere? I'm always up for an adventure.","ja":"おう、どこかに行くのか?俺の方はいつでも準備できてるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kibaou_1#originalText","id":"talk.vc.home_touch_kibaou_1","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"喂！你摸什么摸。","en":"Hey! Where do ya think you're touching?!","ja":"コラ!なに触ってきとんねん"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kibaou_2#originalText","id":"talk.vc.home_touch_kibaou_2","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"干嘛，你很烦人耶。不要随便碰我。","en":"Agh, get your hands off me, you octopus!","ja":"なんや、うっとおしいな気安く触るんやない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kibaou_3#originalText","id":"talk.vc.home_touch_kibaou_3","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"啊，我身上沾到脏东西？……喂，我自己会弄掉！","en":"Oh, was there some lint on me? I mean, hey! I can get that myself!","ja":"あ、ゴミ、付いてたか?……て、自分で取るわ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kibaou_4#originalText","id":"talk.vc.home_touch_kibaou_4","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"怎么，想打吗？我随时奉陪。","en":"Oh, you wanna fight? I'm always up for it.","ja":"なんや、やる気か?わいはいつでも相手になるで"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kibaou_5#originalText","id":"talk.vc.home_touch_kibaou_5","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"你也靠太近了！","en":"Ack! You're too close!","ja":"距離が近いねんお前は!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kibaou_8#originalText","id":"talk.vc.home_touch_kibaou_8","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"差不多该换铠甲了啊……呃，跟你没关系吧！","en":"Maybe I should change my armor... Hey! This has nothing to do with you!","ja":"そろそろ鎧も変えんとな……って、ジブンには関係ないやろっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_1#originalText","id":"talk.vc.home_touch_kirito_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯？怎么了吗？","en":"Hm... something wrong?","ja":"ん? どうかしたか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_2#originalText","id":"talk.vc.home_touch_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哈哈，很痒耶！","en":"Haha! That tickles!","ja":"ははっくすぐったいな!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_3#originalText","id":"talk.vc.home_touch_kirito_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我、我说啊，这要是被人看见，不就很丢脸吗？","en":"L-listen, I don't want anyone to see us like this. It's awkward.","ja":"あ、あのな、誰かに見られたら恥ずかしいだろ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_4#originalText","id":"talk.vc.home_touch_kirito_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哇！吓死我了。有什么事吗？","en":"Whoa! You surprised me! Did you want something?","ja":"わっ! びっくりしたなんか用か?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_5#originalText","id":"talk.vc.home_touch_kirito_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哇，喂！既然如此，看我加倍搔回去！","en":"Agh! Hey! Oooh, you asked for it. Tickle counter attaaack!","ja":"わっ、こらっ!こうなったらくすぐり倍返しだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_8#originalText","id":"talk.vc.home_touch_kirito_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"身高差不多呢。我们就来比比看，谁会长得比较高吧。","en":"Looks like we're the same height. Let's compete to see who can grow bigger.","ja":"いまのところ身長は同じくらいだなどっちがでかくなるか勝負しようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_child_1#originalText","id":"talk.vc.home_touch_kirito_child_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔，你好大的胆子！接下来换我了！","en":"Ooh, you did it! Okay, now it's my turn!","ja":"お、やったな! 今度はこっちの番だ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_child_2#originalText","id":"talk.vc.home_touch_kirito_child_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我的头发总是会翘起来。","en":"My hair is always so spiky.","ja":"俺の髪は、いっつもツンツンしてるんだよなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_child_3#originalText","id":"talk.vc.home_touch_kirito_child_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"怎么说，你是不是把我当小孩子看啊？","en":"Hey, are you treating me like a kid?","ja":"なんか、俺を子ども扱いしてないか? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_child_4#originalText","id":"talk.vc.home_touch_kirito_child_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔，要用木剑分出高下吗？正合我意！","en":"Ooh, you want to fight with practice swords? Bring it!","ja":"お、木剣で勝負か? 望むところだ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_child_5#originalText","id":"talk.vc.home_touch_kirito_child_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂，你不要弄我的肚子……很痒啦！","en":"Hey, stay away from the belly! That tickles!","ja":"おい、腹はやめてくれ……くすぐったいんだってば! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_child_8#originalText","id":"talk.vc.home_touch_kirito_child_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯，怎么了？如果你是要邀我去玩，我随时欢迎喔！","en":"Hm? You wanna play? I'm always up for that!","ja":"ん、なんだ? 遊びの誘いならいつでも歓迎だぜ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_klein_1#originalText","id":"talk.vc.home_touch_klein_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"你说这个头巾？这可是我的标志喔！","en":"This bandana? It's my signature look!","ja":"このバンダナか?こりゃオレのシンボルマークよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_klein_2#originalText","id":"talk.vc.home_touch_klein_2","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"这么说来，初次见面的时候，我们双方的脸都完全不一样呢。","en":"That's right, the first time we met, we both looked like other people.","ja":"そう言えば、最初にあった時はお互い別人の顔だったなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_klein_3#originalText","id":"talk.vc.home_touch_klein_3","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"摸男人的头发到底有什么好玩的啊？","en":"Uh, yeah, that's my hair. Is it really that much fun to touch?","ja":"男の髪の毛触ってよぉいったい何が楽しいんだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_klein_4#originalText","id":"talk.vc.home_touch_klein_4","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"这里明明是虚拟世界，被碰触的感觉却很真实耶。","en":"Even though we're in a virtual world, I can totally feel you touching me.","ja":"仮想世界なのに、ずいぶんしっかり触られた感覚があるんだな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_klein_5#originalText","id":"talk.vc.home_touch_klein_5","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"所以我说了，男人间互相摸来摸去，也只会感到空虚啊……","en":"I don’t know, dude... I think that just makes me feel lonely...","ja":"だからよぉ、男同士で触りっこしても、虚しいだけだろうが……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_klein_8#originalText","id":"talk.vc.home_touch_klein_8","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"嗨，找我有事吗？我随时都能跟你组队喔！","en":"Hey, there. What's up? I'm always up for joining your party, if that's what you want.","ja":"おう、オレに用事か?パーティなら、いつでも組んでやるぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kuradeel_1#originalText","id":"talk.vc.home_touch_kuradeel_1","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"能被你亲手触碰……我克拉帝尔，光荣至极！","en":"Touching me yourself? Kuradeel is indeed honored!","ja":"手ずから触れていただけるとは……クラディール、光栄の至りです!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kuradeel_2#originalText","id":"talk.vc.home_touch_kuradeel_2","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"啊啊……再来，请再多摸我一点！","en":"Ohhh, yes, yes... Please, rub me more!","ja":"ああ……もっと、もっとなでてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kuradeel_3#originalText","id":"talk.vc.home_touch_kuradeel_3","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"我可以把这视为亲爱的证明吧？","en":"May I take this as a symbol of your affection?","ja":"これは、親愛の証と受け取っていいのでしょうな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kuradeel_4#originalText","id":"talk.vc.home_touch_kuradeel_4","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"在这种地方……你也很大胆呢。","en":"Wow, so bold... In broad daylight, no less.","ja":"このようなところで……あなたも大胆な人だ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kuradeel_5#originalText","id":"talk.vc.home_touch_kuradeel_5","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"呵，只要你希望，我随时都……","en":"Heh. If you wish it, I am always willing.","ja":"ふっ、あなたが望むなら私はいつでも……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kuradeel_8#originalText","id":"talk.vc.home_touch_kuradeel_8","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"透过身体的接触来确认彼此的感情。是这样对吧？","en":"When bodies connect, minds also connect, wouldn't you say?","ja":"体に触れ合うことで気持ちを確かめ合うということですな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kureha_1#originalText","id":"talk.vc.home_touch_kureha_1","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"你是不是太装熟了啊？突然就摸别人的头……","en":"Isn't it a little comfortable? To suddenly pet your head...","ja":"ちょっと気安いんじゃない?いきなり、頭を撫でるなんて……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kureha_2#originalText","id":"talk.vc.home_touch_kureha_2","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"我的侧边单马尾很可爱吧？这可是我的注册商标喔！","en":"Isn't my side tail cute? It's my own personal trademark!","ja":"サイドテール、かわいいでしょ?あたしのトレードマークだからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kureha_3#originalText","id":"talk.vc.home_touch_kureha_3","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"真是的，别看我这样，等级意外地蛮高的喔！可以不要这样对我吗！","en":"Looks like even with this ranking we're on the higher end! So stop doing that!","ja":"もう、これでもランキングは割と高い方なんだからね!そういう扱いはやめて!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kureha_4#originalText","id":"talk.vc.home_touch_kureha_4","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"等一下！突然干嘛啦！","en":"Wait a minute! What are you doing all of a sudden!","ja":"ちょっと!いきなり何するのよっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kureha_5#originalText","id":"talk.vc.home_touch_kureha_5","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"就算不碰我的，你周围也有一堆人可以给你摸吧……","en":"You have plenty of options, right? It doesn’t have to be me...","ja":"あたしの触らなくたっていっぱいあるでしょう?あなたの周りには……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kureha_6#originalText","id":"talk.vc.home_touch_kureha_6","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"粉红色的确是很显眼啦……但是至少在游戏里，想穿可爱的衣服嘛。","en":"This pink really makes me stand out... But I want to wear cute clothing in-game.","ja":"確かにピンクは目立つけど……ゲームの中でくらいかわいい服を着たいの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kureha_7#originalText","id":"talk.vc.home_touch_kureha_7","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"做这种事，被你老婆看到怎么办！？你会连累我的！","en":"What would your wife think if she saw this?! Keep me out of it!","ja":"そんなことして、奥さんに見られたらどうするんですか!?あたしまで巻き込まれちゃう!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kureha_8#originalText","id":"talk.vc.home_touch_kureha_8","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"真不愧是光剑的专家，动作好快……下次一定要躲过去！","en":"As expected from the expert Photon swordsman, your motions are quick... I'll be avoiding the next one!","ja":"さすが、光剣の達人だけあって身のこなしが素早い……次は避けてみせるっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_1#originalText","id":"talk.vc.home_touch_leafa_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"咦，什么……？你、你突然这样吓到我了……","en":"Huh? What?! J-jeez. You startled me.","ja":"え、なに……? い、いきなりはびっくりするよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_2#originalText","id":"talk.vc.home_touch_leafa_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"小时候，我常常要你这样摸我呢……","en":"When I was a baby, you used to pat my head like this a lot.","ja":"ちっちゃい頃は、こうやってよく撫でてもらったよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_3#originalText","id":"talk.vc.home_touch_leafa_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"讨厌，很痒啦！看我怎么回敬你！","en":"Hey! That tickles! Aha! The tables have turned!","ja":"もう、くすぐったいってば! この、お返しだ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_4#originalText","id":"talk.vc.home_touch_leafa_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"那个……你不要一直盯着我看啦。……真有那么引人注目吗？","en":"Uh...could you, like, not stare at me? Unless...do I really stand out that much?","ja":"あの……ジロジロ見ないでね……やっぱり、そんなに目立つ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_5#originalText","id":"talk.vc.home_touch_leafa_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"咿啊啊！你知道那里是我的弱点吧！？","en":"Eeep! You know that's my weak spot, don't you?!","ja":"ひゃああっ! そこは弱点だって知ってるでしょ!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_6#originalText","id":"talk.vc.home_touch_leafa_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"喂！？我、我还是很在意的，不要捉弄我啦……","en":"Whoa, dude?! I may not look it, but I'm pretty self-conscious. So, don't tease me.","ja":"ちょっと!?こ、これでも気にしてるんだからからかわないでよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_7#originalText","id":"talk.vc.home_touch_leafa_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"喂！就算我们是家人，还是有不能摸的地方啦！","en":"Hey! Even though we're family, there's still \"good touch\" and \"bad touch\"!","ja":"こら! いくら家族でも、触ったらダメなところもあるんだから! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_8#originalText","id":"talk.vc.home_touch_leafa_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"怎么了？你要出门吗？","en":"What's up? Going out somewhere?","ja":"どうしたの? どこかにお出かけする? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_linel_1#originalText","id":"talk.vc.home_touch_linel_1","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"那、那个……被你那样摸，我会痒……","en":"That tickles when you touch me like that...","ja":"そ、その……そんなに撫でられるとくすぐったくて……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_linel_2#originalText","id":"talk.vc.home_touch_linel_2","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"呀！？你、你不会弄痛我吗……？","en":"Eep?! Y-you aren’t going to hurt me, are you?","ja":"ひゃっ!?い、痛くしないですか……?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_linel_3#originalText","id":"talk.vc.home_touch_linel_3","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"……我的辫子，一直都是赛尔帮忙绑的。","en":"Fizel always braids my hair for me.","ja":"……三つ編みは、ゼルがいつもやってくれるんです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_linel_4#originalText","id":"talk.vc.home_touch_linel_4","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"没错，那里就是心脏。只要刺向这里，就能确实地一击必杀喔。","en":"Yes, that's the heart. If you stab me there, I will die instantly.","ja":"そう、そこが心臓ですここを刺せば、一撃でちゃんと殺せますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_linel_5#originalText","id":"talk.vc.home_touch_linel_5","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"呀！？摸侧腹会痒啦……","en":"Eep?! Not my sides...that tickles!","ja":"きゃっ!?脇腹は、くすぐったいです……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_linel_6#originalText","id":"talk.vc.home_touch_linel_6","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"赛尔也常常会摸这附近。因为离心脏很近。","en":"Fizel touches me there often. Because the heart is near, she says.","ja":"ゼルもよくそこ辺りを触ってました心臓が近いからって"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_linel_7#originalText","id":"talk.vc.home_touch_linel_7","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"希望我的身体能变得跟亚多米尼史特蕾达大人一样……","en":"I hope that someday, I have a body like the Lady Administrator.","ja":"アドミニストレータ様みたいなお体に、なれるといいなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_linel_8#originalText","id":"talk.vc.home_touch_linel_8","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"你有什么事吗？如果能立下功绩，我什么都会做。","en":"You wish to speak to me? If there is anything I can do for you, ask away.","ja":"なにか用事ですか?手柄を立てられるならなんでもやります"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lipia_1#originalText","id":"talk.vc.home_touch_lipia_1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"啊……那个，我还在做任务……","en":"Ah... That... I'm still in the middle of a mission...","ja":"あっ……その、まだ任務の途中で……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lipia_2#originalText","id":"talk.vc.home_touch_lipia_2","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"长头发虽然在战斗时会有点不方便，但这样也有这样的好处……","en":"Long hair is an inconvenience in battle, but it does come in handy here and there...","ja":"長い髪は戦闘に不便ですがこれはこれで役に立つこともありまして……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lipia_3#originalText","id":"talk.vc.home_touch_lipia_3","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"阁下的手总是很温柔。就算您再粗暴一点我也不会有事的喔？","en":"My Lord's hand is always so gentle. Even if you were to be rougher with me I won't break away.","ja":"閣下の手はいつもお優しいもっと手荒に扱っても私は壊れはしませんよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lipia_4#originalText","id":"talk.vc.home_touch_lipia_4","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"只要是阁下所希望的我当然……但是，在这里，那个……","en":"If my Lord desires so... Of course... But, here...","ja":"閣下がお望みであればもちろん……ですが、ここでは、その……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lipia_5#originalText","id":"talk.vc.home_touch_lipia_5","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"要是我拥有阁下那般强壮的身体，说不定我也能走上更高的位置。","en":"If I had a muscular body such as my Lord, I too would be able to stand tall.","ja":"閣下のようなたくましい肉体があれば私ももっと、高みに上れるのですが"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lipia_8#originalText","id":"talk.vc.home_touch_lipia_8","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"阁下，别再调侃我了。……周边还有人在看的。","en":"My Lord, we're playing around too much ...People are looking.","ja":"閣下、お戯れが過ぎます……人目が、ございますから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_1#originalText","id":"talk.vc.home_touch_lisbeth_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"还是我也把头发留长好了……那样比较有女人味，对吧？","en":"Maybe I should grow out my hair, too? That's a more girlish look, huh.","ja":"あたしも、髪伸ばそうかな……その方が女の子っぽいよね? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_2#originalText","id":"talk.vc.home_touch_lisbeth_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"老是马上就这样……受不了，你就是这点讨厌啦……","en":"I told you to quit that...","ja":"そうやってすぐ……もうだからダメなのよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_3#originalText","id":"talk.vc.home_touch_lisbeth_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"喂，碰耳朵犯规啦！我的背会起鸡皮疙瘩！","en":"Hey, not the ears! There's chills down my spine!","ja":"ちょ、耳はダメ! 背筋がぞわってするの! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_4#originalText","id":"talk.vc.home_touch_lisbeth_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"真可惜。我那里可是有胸甲挡着！","en":"Sorry, stud. I'm wearing armor!","ja":"残念そこはブレストアーマーで守ってありますから! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_5#originalText","id":"talk.vc.home_touch_lisbeth_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"喂，很痒耶！我可也还是个女孩子喔！","en":"Hey! That tickles! And have you forgotten I'm a girl?","ja":"ちょっと、なにやってるのよ!?あたしだって女の子なんですからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_6#originalText","id":"talk.vc.home_touch_lisbeth_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你那只手想干嘛？不会是想做什么失礼的事情吧？","en":"Hey. Where do you think you're touching me? I hope your mind's not in a dirty place.","ja":"なあに、その手は不埒なこと考えてないでしょうね?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_7#originalText","id":"talk.vc.home_touch_lisbeth_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你不是都有老婆了吗！小心我去告状喔，告状！","en":"Aren't you married?! That's it. I'm reporting you!","ja":"あんたにはお嫁さんがいるでしょ! 通報するわよ、通報! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_8#originalText","id":"talk.vc.home_touch_lisbeth_8","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"嗯？什么事？找我出任务的话，我很欢迎喔。","en":"Hm? What's up? If it's a Quest, I'm in.","ja":"ん、なあに? クエストのお誘いなら歓迎よ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mary_1#originalText","id":"talk.vc.home_touch_mary_1","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"啊……真是的，把人家当孩子……我马上就会长得比姊姊还高！","en":"Hey! Stop treating me like a little girl. I'm gonna be bigger than you someday!","ja":"あっ……もう、子ども扱いして……すぐお姉ちゃんより大きくなるから!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mary_2#originalText","id":"talk.vc.home_touch_mary_2","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我们两人戴着成对的发饰啊……看着这个，就会觉得一个人也不寂寞。","en":"Our hair ribbons match... Knowing this makes me feel less alone somehow.","ja":"髪飾り、お揃いなんだよね……これを見てると、ひとりでも寂しくないって気がするの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mary_3#originalText","id":"talk.vc.home_touch_mary_3","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"小时候，姊姊也曾像这样摸摸我对吧？姊姊这样做，我就会莫名地感到安心。","en":"You probably patted me like this when I was little, too. It feels so warm...and comforting.","ja":"もっと小さかった頃もこうやって撫でてくれたよね撫でてもらうと、なんだか安心する"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mary_4#originalText","id":"talk.vc.home_touch_mary_4","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我是不是也能变得跟姊姊一样大呢……这个地方。","en":"Sister...I wonder if I'll become just as big as you someday? You know...here.","ja":"わたしもお姉ちゃんみたいに大きくなるかなあ……ここ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mary_5#originalText","id":"talk.vc.home_touch_mary_5","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"怎么了？呵呵，姊姊变得反倒像是我的妹妹呢。","en":"What's gotten into you? Haha. Now I feel like I'm the big sister.","ja":"どうしたの?ふふ、お姉ちゃんが妹になったみたいだよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mary_6#originalText","id":"talk.vc.home_touch_mary_6","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"没事的，我今天脚也不痛，有精神得很！不用担心我喔。","en":"Don't worry. My foot doesn't hurt today and I feel great! I'll be fine, okay?","ja":"大丈夫! 今日は足も痛くないし元気いっぱいだから!心配しないでね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mary_7#originalText","id":"talk.vc.home_touch_mary_7","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"如果我也成为姊姊那样的剑士，是不是就能穿上一样的衣服呢……","en":"When I become a swordsman like you, Sister, will I be able to dress the same way?","ja":"わたしも、お姉ちゃんみたいな剣士になったら、同じような格好ができるのかなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mary_8#originalText","id":"talk.vc.home_touch_mary_8","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"今天愿意陪我一起睡？……真的吗！？耶！","en":"You'll sleep here with me tonight? Really?! That's wonderful!","ja":"今日は一緒に寝てくれる?……ほんと!?やったあ!"},"kind":"dialogue"}]};
